// reproduce-lh-simulate.js
const lighthouse = require('lighthouse');
const chromeLauncher = require('chrome-launcher');

(async () => {
  // 1. Launch a headless Chrome instance
  const chrome = await chromeLauncher.launch({
    chromeFlags: ['--headless', '--disable-gpu']
  });

  // 2. Configure Lighthouse to use `simulate` throttling
  const options = {
    logLevel: 'info',
    output: 'json',
    onlyCategories: ['performance'],
    port: chrome.port,
    throttlingMethod: 'simulate',
    throttling: {
      // network round-trip time in ms
      rttMs: 150,
      // throughput in Kbps
      throughputKbps: 1600,
      // CPU slowdown multiplier
      cpuSlowdownMultiplier: 4,
    },
    // Increase maxWaitForLoad to see if waiting longer picks up extra layout shifts
    maxWaitForLoad: 45000,
    maxWaitForFcp: 30000,
  };

  // 3. Run Lighthouse against the Venia page
  const runnerResult = await lighthouse(
    'https://develop.pwa-venia.com/venia-bottoms.html',
    options
  );

  // 4. Extract and log the relevant metrics
  const lhr = runnerResult.lhr;
  console.log('Performance score:', lhr.categories.performance.score * 100);
  console.log('First Contentful Paint (s):', lhr.audits['first-contentful-paint'].displayValue);
  console.log('Speed Index (s):', lhr.audits['speed-index'].displayValue);
  console.log('Largest Contentful Paint (s):', lhr.audits['largest-contentful-paint'].displayValue);
  console.log('Total Blocking Time (ms):', lhr.audits['total-blocking-time'].displayValue);
  console.log('Cumulative Layout Shift:', lhr.audits['cumulative-layout-shift'].displayValue);

  // 5. Tear down Chrome
  await chrome.kill();
})();
